} from './types';

/**
 * Coordinates glucose record persistence and history tracking.
 */
export class GlucoseRecordService {
  private readonly repository: GlucoseRecordRepository;

  private readonly historyService: GlucoseRecordHistoryService;

  /**
   * Creates a new glucose record service.
   *
   * @param repository - The persistence repository.
   * @param historyService - The audit history service.
   */
  public constructor(
    repository: GlucoseRecordRepository = new GlucoseRecordRepository(),
    historyService: GlucoseRecordHistoryService = new GlucoseRecordHistoryService(),
  ) {
    this.repository = repository;
    this.historyService = historyService;
  }

  /**
   * Creates a new glucose record and appends a history event.
   *
   * @param input - The record values to create.
   * @returns The created record.
   */
  public async createRecord(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    this.validateCreateInput(input);
    const created: GlucoseRecord = await this.repository.create(input);
    this.historyService.appendCreated(created);
    return created;
  }

  /**
   * Lists all records for a patient.
   *
   * @param patientId - The patient identifier.
   * @returns The matching records.
   */
  public async listRecords(patientId: string): Promise<GlucoseRecord[]> {
    this.validateNonEmptyString(patientId, 'patientId');
    return this.repository.list(patientId);
  }

  /**
   * Retrieves a record by its identifier.
   *
   * @param id - The record identifier.
   * @returns The record if found, otherwise null.
   */
  public async getRecord(id: string): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    return this.repository.getById(id);
  }

  /**
   * Updates a record and appends a history event if found.
   *
   * @param id - The record identifier.
   * @param input - The fields to update.
   * @returns The updated record, or null if not found.
   */
  public async updateRecord(
    id: string,
    input: GlucoseRecordUpdateInput,
  ): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    this.validateUpdateInput(input);

    const before: GlucoseRecord | null = await this.repository.getById(id);
    if (before === null) {
      return null;
    }

    const after: GlucoseRecord | null = await this.repository.update(id, input);
    if (after === null) {
      return null;
    }

    this.historyService.appendUpdated(before, after);
    return after;
  }

  /**
   * Deletes a record and appends a history event if found.
   *
   * @param id - The record identifier.
   * @returns True if a record was deleted; otherwise false.
   */
  public async deleteRecord(id: string): Promise<boolean> {
    this.validateNonEmptyString(id, 'id');

    const existing: GlucoseRecord | null = await this.repository.getById(id);
    if (existing === null) {
      return false;
    }

    const deleted: boolean = await this.repository.delete(id);
    if (deleted) {
      this.historyService.appendDeleted(existing);
    }

    return deleted;
  }

  /**
   * Lists history events for a specific record.
   *
   * @param recordId - The record identifier.
   * @returns The matching history events.
   */
  public async getRecordHistory(recordId: string): Promise<GlucoseRecordHistoryEvent[]> {
    this.validateNonEmptyString(recordId, 'recordId');
    return this.historyService.listByRecordId(recordId);
  }

  /**
   * Lists all history events for a patient.
   *
   * @param patientId - The patient identifier.
   * @returns The matching history events.
   */
  public async listPatientHistory(patientId: string): Promise<GlucoseRecordHistoryEvent[]> {
    this.validateNonEmptyString(patientId, 'patientId');
    return this.historyService.listAll(patientId);
  }

  private validateCreateInput(input: GlucoseRecordCreateInput): void {
    if (input === null || input === undefined) {
      throw new Error('input is required.');
    }
    this.validateNonEmptyString(input.patientId, 'input.patientId');
    this.validateNonEmptyString(input.measuredAt, 'input.measuredAt');
    this.validateNonEmptyString(input.unit, 'input.unit');
    if (typeof input.glucoseValue !== 'number' || Number.isNaN(input.glucoseValue)) {
      throw new Error('input.glucoseValue must be a valid number.');
    }
    if (input.note !== undefined && input.note === null) {
      throw new Error('input.note cannot be null.');
    }
  }

  private validateUpdateInput(input: GlucoseRecordUpdateInput): void {
    if (input === null || input === undefined) {
      throw new Error('input is required.');
    }
    if (input.measuredAt !== undefined) {
      this.validateNonEmptyString(input.measuredAt, 'input.measuredAt');
    }
    if (input.unit !== undefined) {
      this.validateNonEmptyString(input.unit, 'input.unit');
    }
    if (input.glucoseValue !== undefined && (typeof input.glucoseValue !== 'number' || Number.isNaN(input.glucoseValue))) {
      throw new Error('input.glucoseValue must be a valid number.');
    }
    if (input.note !== undefined && input.note === null) {
      throw new Error('input.note cannot be null.');
    }
  }

  private validateNonEmptyString(value: string, parameterName: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`${parameterName} must be a non-empty string.`);
    }
  }
}

