  const service: GlucoseRecordService = new GlucoseRecordService();

  const created = await service.createRecord({
    patientId: 'patient-1',
    measuredAt: '2024-01-01T10:00:00.000Z',
    glucoseValue: 5.6,
    unit: 'mmol/L',
    note: 'fasting',
  });

  if (created.id !== '1') {
    console.error('Expected created record id to be 1.');
    process.exit(1);
  }

  const fetched = await service.getRecord(created.id);
  if (fetched === null || fetched.patientId !== 'patient-1') {
    console.error('Expected getRecord to return the created record.');
    process.exit(1);
  }

  const updated = await service.updateRecord(created.id, { glucoseValue: 6.1, note: undefined });
  if (updated === null || updated.glucoseValue !== 6.1) {
    console.error('Expected updateRecord to update the glucose value.');
    process.exit(1);
  }

  const records = await service.listRecords('patient-1');
  if (records.length !== 1) {
    console.error('Expected listRecords to return one record.');
    process.exit(1);
  }

  const history = await service.getRecordHistory(created.id);
  if (history.length !== 2 || history[0].action !== 'created' || history[1].action !== 'updated') {
    console.error('Expected record history to contain created and updated events.');
    process.exit(1);
  }

  const patientHistory = await service.listPatientHistory('patient-1');
  if (patientHistory.length !== 2) {
    console.error('Expected patient history to contain two events.');
    process.exit(1);
  }

  const deleted = await service.deleteRecord(created.id);
  if (!deleted) {
    console.error('Expected deleteRecord to return true.');
    process.exit(1);
  }

  const deletedHistory = await service.getRecordHistory(created.id);
  if (deletedHistory.length !== 3 || deletedHistory[2].action !== 'deleted') {
    console.error('Expected record history to contain deleted event after deleteRecord.');
    process.exit(1);
  }

  const missing = await service.getRecord(created.id);
  if (missing !== null) {
    console.error('Expected deleted record to be missing.');
    process.exit(1);
  }

  const emptyHistory = await service.getRecordHistory('missing-record');
  if (emptyHistory.length !== 0) {
    console.error('Expected missing record history to be empty.');
    process.exit(1);
  }

  let threw: boolean = false;
  try {
    await service.createRecord({
      patientId: '',
      measuredAt: '2024-01-01T10:00:00.000Z',
      glucoseValue: 5.6,
      unit: 'mmol/L',
    });
  } catch {
    threw = true;
  }

  if (!threw) {
    console.error('Expected createRecord to reject an empty patientId.');
    process.exit(1);
  }

  console.log('PASS');
}

main().catch((error: unknown) => {
  console.error(error);
  process.exit(1);
});

