import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord } from './types';

/**
 * View model for loading and sorting glucose measurement records.
 */
export class GlucoseRecordListViewModel {
  private readonly recordService: GlucoseRecordService;

  private lastPatientId: string | null;

  /**
   * Creates a new glucose record list view model.
   *
   * @param recordService - The glucose record service dependency.
   */
  public constructor(recordService: GlucoseRecordService = new GlucoseRecordService()) {
    this.recordService = recordService;
    this.lastPatientId = null;
  }

  /**
   * Loads records for the given patient and sorts them by measuredAt descending.
   *
   * @param patientId - The patient identifier.
   * @returns The sorted records.
   */
  public async load(patientId: string): Promise<GlucoseRecord[]> {
    this.validateNonEmptyString(patientId, 'patientId');
    this.lastPatientId = patientId;

    const records: GlucoseRecord[] = await this.recordService.listRecords(patientId);
    return this.sortByMeasuredAtDescending(records);
  }

  /**
   * Reloads records for the most recently loaded patient and sorts them by measuredAt descending.
   *
   * @returns The sorted records.
   */
  public async refresh(): Promise<GlucoseRecord[]> {
    if (this.lastPatientId === null) {
      throw new Error('No patient has been loaded yet.');
    }

    const records: GlucoseRecord[] = await this.recordService.listRecords(this.lastPatientId);
    return this.sortByMeasuredAtDescending(records);
  }

  /**
   * Sorts records by measuredAt in descending order without mutating the input array.
   *
   * @param records - The records to sort.
   * @returns A new array sorted by measuredAt descending.
   */
  public sortByMeasuredAtDescending(records: GlucoseRecord[]): GlucoseRecord[] {
    if (!Array.isArray(records)) {
      throw new Error('records must be an array.');
    }

    const clonedRecords: GlucoseRecord[] = records.map((record: GlucoseRecord) => ({ ...record }));
    clonedRecords.sort((left: GlucoseRecord, right: GlucoseRecord) => {
      const leftTime: number = Date.parse(left.measuredAt);
      const rightTime: number = Date.parse(right.measuredAt);

      if (Number.isNaN(leftTime) && Number.isNaN(rightTime)) {
        return 0;
      }
      if (Number.isNaN(leftTime)) {
        return 1;
      }
      if (Number.isNaN(rightTime)) {
        return -1;
      }

      return rightTime - leftTime;
    });

    return clonedRecords;
  }

