import type { GlucoseRecordHistoryEvent } from './history-types';
import type { GlucoseRecord } from './types';

/**
 * Asserts that a condition is true.
 *
 * @param condition - The condition to verify.
 * @param message - The failure message.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

/**
 * Asserts that two values are deeply equal by comparing their JSON representations.
 *
 * @param actual - The actual value.
 * @param expected - The expected value.
 * @param message - The failure message.
 */
function assertDeepEqual<T>(actual: T, expected: T, message: string): void {
  const actualJson: string = JSON.stringify(actual);
  const expectedJson: string = JSON.stringify(expected);
  assert(actualJson === expectedJson, `${message}\nExpected: ${expectedJson}\nActual:   ${actualJson}`);
}

/**
 * Creates a valid glucose record for use in tests.
 *
 * @param overrides - Optional field overrides.
 * @returns A glucose record.
 */
function createRecord(overrides: Partial<GlucoseRecord> = {}): GlucoseRecord {
  return {
    id: 'record-1',
    patientId: 'patient-1',
    measuredAt: '2024-01-01T00:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
    ...overrides,
  };
}

/**
 * Returns the action sequence from a list of history events.
 *
 * @param events - The events to inspect.
 * @returns The event actions in order.
 */
function actionsOf(events: GlucoseRecordHistoryEvent[]): Array<'created' | 'updated' | 'deleted'> {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action);
}

/**
 * Runs a callback with fake timers and restores real timers afterward.
 *
 * @param callback - The callback to execute.
 * @returns The callback result.
 */
async function runWithFakeTimers<T>(callback: () => Promise<T>): Promise<T> {
  vi.useFakeTimers();
  try {
    return await callback();
  } finally {
    vi.useRealTimers();
  }
}

describe('GlucoseRecordHistoryService', () => {
  it('appendCreated/appendUpdated/appendDeleted add events', async () => {
    await runWithFakeTimers(async () => {
      const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();
      const created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
      const updated: GlucoseRecord = createRecord({
        id: 'record-1',
        patientId: 'patient-1',
        glucoseValue: 125,
        measuredAt: '2024-01-01T01:00:00.000Z',
        updatedAt: '2024-01-01T01:00:00.000Z',
      });
      const deleted: GlucoseRecord = createRecord({
        id: 'record-2',
        patientId: 'patient-1',
        glucoseValue: 90,
        measuredAt: '2024-01-01T02:00:00.000Z',
        updatedAt: '2024-01-01T02:00:00.000Z',
      });

      vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
      service.appendCreated(created);
      vi.setSystemTime(new Date('2024-01-01T00:00:01.000Z'));
      service.appendUpdated(created, updated);
      vi.setSystemTime(new Date('2024-01-01T00:00:02.000Z'));
      service.appendDeleted(deleted);

      const recordOneEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-1');
      const recordTwoEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-2');
      const patientEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');

      assert(recordOneEvents.length === 2, 'Expected two events for record-1.');
      assertDeepEqual(actionsOf(recordOneEvents), ['created', 'updated'], 'Expected record-1 actions to match.');
      assertDeepEqual(recordOneEvents[0]?.snapshot, created, 'Expected created snapshot to be preserved.');
      assertDeepEqual(recordOneEvents[1]?.snapshot, updated, 'Expected updated snapshot to be preserved.');

      assert(recordTwoEvents.length === 1, 'Expected one event for record-2.');
      assertDeepEqual(actionsOf(recordTwoEvents), ['deleted'], 'Expected record-2 actions to match.');
      assertDeepEqual(recordTwoEvents[0]?.snapshot, deleted, 'Expected deleted snapshot to be preserved.');

      assert(patientEvents.length === 3, 'Expected three events for patient-1.');
      assertDeepEqual(
        actionsOf(patientEvents),
        ['created', 'updated', 'deleted'],
        'Expected patient events to be returned in insertion order.',
      );
    });
  });

  it("listByRecordId returns only the matching record's events", async () => {
    await runWithFakeTimers(async () => {
      const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();
      const recordACreated: GlucoseRecord = createRecord({
        id: 'record-a',
        patientId: 'patient-1',
        createdAt: '2024-01-01T00:00:00.000Z',
        updatedAt: '2024-01-01T00:00:00.000Z',
      });
      const recordBCreated: GlucoseRecord = createRecord({
        id: 'record-b',
        patientId: 'patient-1',
        glucoseValue: 111,
        createdAt: '2024-01-01T00:00:01.000Z',
        updatedAt: '2024-01-01T00:00:01.000Z',
      });
      const recordAUpdated: GlucoseRecord = createRecord({
        id: 'record-a',
        patientId: 'patient-1',
        glucoseValue: 130,
        updatedAt: '2024-01-01T00:00:02.000Z',
      });
      const recordBDeleted: GlucoseRecord = createRecord({
        id: 'record-b',
        patientId: 'patient-1',
        glucoseValue: 111,
        createdAt: '2024-01-01T00:00:03.000Z',
        updatedAt: '2024-01-01T00:00:03.000Z',
      });

      vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
      service.appendCreated(recordACreated);
      vi.setSystemTime(new Date('2024-01-01T00:00:01.000Z'));
      service.appendCreated(recordBCreated);
      vi.setSystemTime(new Date('2024-01-01T00:00:02.000Z'));
      service.appendUpdated(recordACreated, recordAUpdated);
      vi.setSystemTime(new Date('2024-01-01T00:00:03.000Z'));
      service.appendDeleted(recordBDeleted);

      const recordAEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-a');
      const recordBEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-b');

      assertDeepEqual(actionsOf(recordAEvents), ['created', 'updated'], 'Expected record-a events only.');
      assert(recordAEvents.every((event: GlucoseRecordHistoryEvent) => event.recordId === 'record-a'), 'Expected all record-a events to match record-a.');
      assertDeepEqual(recordAEvents[0]?.snapshot, recordACreated, 'Expected first record-a snapshot to match.');
      assertDeepEqual(recordAEvents[1]?.snapshot, recordAUpdated, 'Expected second record-a snapshot to match.');

      assertDeepEqual(actionsOf(recordBEvents), ['created', 'deleted'], 'Expected record-b events only.');
      assert(recordBEvents.every((event: GlucoseRecordHistoryEvent) => event.recordId === 'record-b'), 'Expected all record-b events to match record-b.');
    });
  });

  it('listAll(patientId) returns events for a patient in insertion order', async () => {
    await runWithFakeTimers(async () => {
      const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

      vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
      service.appendCreated(
        createRecord({
          id: 'record-a',
          patientId: 'patient-1',
          createdAt: '2024-01-01T00:00:00.000Z',
          updatedAt: '2024-01-01T00:00:00.000Z',
        }),
      );
      vi.setSystemTime(new Date('2024-01-01T00:00:01.000Z'));
      service.appendCreated(
        createRecord({
          id: 'record-b',
          patientId: 'patient-2',
          createdAt: '2024-01-01T00:00:01.000Z',
          updatedAt: '2024-01-01T00:00:01.000Z',
        }),
      );
      vi.setSystemTime(new Date('2024-01-01T00:00:02.000Z'));
      service.appendUpdated(
        createRecord({ id: 'record-a', patientId: 'patient-1' }),
        createRecord({
          id: 'record-a',
          patientId: 'patient-1',
          glucoseValue: 140,
          updatedAt: '2024-01-01T00:00:02.000Z',
        }),
      );
      vi.setSystemTime(new Date('2024-01-01T00:00:03.000Z'));
      service.appendDeleted(
        createRecord({
          id: 'record-c',
          patientId: 'patient-1',
          glucoseValue: 95,
          createdAt: '2024-01-01T00:00:03.000Z',
          updatedAt: '2024-01-01T00:00:03.000Z',
        }),
      );

      const patientOneEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');
      const patientTwoEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-2');

      assertDeepEqual(actionsOf(patientOneEvents), ['created', 'updated', 'deleted'], 'Expected patient-1 events in insertion order.');
      assertDeepEqual(
        patientOneEvents.map((event: GlucoseRecordHistoryEvent) => event.recordId),
        ['record-a', 'record-a', 'record-c'],
        'Expected patient-1 record ids to match.',
      );
      assertDeepEqual(actionsOf(patientTwoEvents), ['created'], 'Expected patient-2 events only.');
      assertDeepEqual(patientTwoEvents.map((event: GlucoseRecordHistoryEvent) => event.recordId), ['record-b'], 'Expected patient-2 record ids to match.');
    });
  });

  it('preserves snapshots when supplied', async () => {
    await runWithFakeTimers(async () => {
      const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();
      const created: GlucoseRecord = createRecord({
        id: 'record-snapshot',
        patientId: 'patient-1',
        note: 'initial note',
      });

      vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
      service.appendCreated(created);

      const events: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-snapshot');
      assert(events.length === 1, 'Expected one event to be returned.');
      assertDeepEqual(events[0]?.snapshot, created, 'Expected snapshot to be preserved exactly.');
    });
  });
});
